ALTER TABLE bookings.customers
  ADD COLUMN IF NOT EXISTS customer_type VARCHAR(20) NOT NULL DEFAULT 'casual'
    CHECK (customer_type IN ('casual', 'contract'));

ALTER TABLE bookings.recurring_rules
  ADD COLUMN IF NOT EXISTS series_reference  VARCHAR(20),
  ADD COLUMN IF NOT EXISTS total_cycles      INT,
  ADD COLUMN IF NOT EXISTS remaining_cycles  INT,
  ADD COLUMN IF NOT EXISTS monthly_fee       NUMERIC(10,2);

-- Ensure billing_day has the right default (may already exist from Migration008)
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'bookings'
      AND table_name   = 'recurring_rules'
      AND column_name  = 'billing_day'
  ) THEN
    ALTER TABLE bookings.recurring_rules ALTER COLUMN billing_day SET DEFAULT 20;
  ELSE
    ALTER TABLE bookings.recurring_rules ADD COLUMN billing_day INT DEFAULT 20
      CHECK (billing_day BETWEEN 1 AND 31);
  END IF;
END;
$$;

CREATE INDEX IF NOT EXISTS idx_recurring_rules_series_ref
  ON bookings.recurring_rules(series_reference);

CREATE INDEX IF NOT EXISTS idx_customers_customer_type
  ON bookings.customers(customer_type);

CREATE INDEX IF NOT EXISTS idx_customers_type_tenant
  ON bookings.customers(tenant_id, customer_type);

CREATE SEQUENCE IF NOT EXISTS bookings.series_reference_seq
  START WITH 1001
  INCREMENT BY 1
  NO MAXVALUE
  CACHE 1;

UPDATE bookings.recurring_rules
SET series_reference = 'RB-' || nextval('bookings.series_reference_seq')::text
WHERE series_reference IS NULL;
